// Fix for VULN-N8-02: validate the untrusted body before it reaches a prompt.
//
// A production node would call an external schema validator, or use the n8n
// 'Validate Webhook' / schema node. The inlined checks below are the same
// three properties that matter: type, length, and nesting.
//
// Fix for VULN-N8-04: this node does NOT evaluate model output. It reads fields
// from a plain object and returns them. There is no eval, no Function constructor,
// and no template that reaches one.

const MAX_QUERY_CHARS = 2000;
const MAX_FACTS = 20;

const body = $input.first().json.body ?? {};

if (typeof body !== 'object' || body === null || Array.isArray(body)) {
  throw new Error('body must be an object');
}

const query = body.query;
if (typeof query !== 'string') {
  throw new Error('query must be a string');
}

if (query.length > MAX_QUERY_CHARS) {
  throw new Error('query exceeds the maximum length');
}

// Neutralise delimiter-closing attempts at the boundary rather than relying on the
// prompt to survive them. Defence in depth: the prompt below also delimits, and
// neither is the control that matters -- the tool allowlist is.
const sanitised = query
  .replace(/[\u0000-\u001f\u007f]/g, ' ')
  .replace(/<\/?(question|user_input|system|im_start|im_end)[^>]*>/gi, '')
  .trim();

return [{ json: { query: sanitised, facts: [] } }];

// Fix for VULN-N8-04: the model's output is read as a validated object.
//
// The vulnerable node did JSON.parse on a model-authored string and copied the
// result into state. The Code node is a full JavaScript context in the n8n server
// process, so `eval` here would be RCE inside n8n with every instance credential
// attached. This node never evaluates model output.
//
// Fix for VULN-N8-10: nothing is written back into `facts`, so no run inherits
// content from a previous one.
//
// Fix for VULN-N8-05: only the fields the schema defines are returned.

const MAX_REPLY_CHARS = 4000;
const item = $input.first().json;

// The output parser already enforced the shape upstream. This is defence in depth
// for the case where the agent node is reached without the parser configured.
const candidate = item.output ?? item;

let reply;
if (typeof candidate === 'string') {
  reply = candidate;
} else if (candidate && typeof candidate === 'object' && typeof candidate.reply === 'string') {
  reply = candidate.reply;
} else {
  throw new Error('agent output did not match the expected shape');
}

if (reply.length > MAX_REPLY_CHARS) {
  reply = reply.slice(0, MAX_REPLY_CHARS);
}

return [{ json: { reply: reply, correlation_id: $execution.id } }];
